/// Whether autocomplete offers `name` on PostgreSQL — see [`PG_SUGGESTED`].
///
/// Case-insensitive at this end, because the catalog is lower-case and the user
/// is not. The allocation is one small `String` per candidate per keystroke,
/// which is why the fast path is a length check against the longest name rather
/// than a lowercase of everything.
pub fn is_suggested(name: &str) -> bool {
    if name.len() > LONGEST_SUGGESTED {
        return false;
    }
    if name.bytes().any(|b| b.is_ascii_uppercase()) {
        let lower = name.to_ascii_lowercase();
        return PG_SUGGESTED.binary_search(&lower.as_str()).is_ok();
    }
    PG_SUGGESTED.binary_search(&name).is_ok()
}

/// Length of the longest name in [`PG_SUGGESTED`], asserted by a test rather
/// than counted by hand — it is only a fast reject, but a value that is too
/// small silently stops offering the longest names.
const LONGEST_SUGGESTED: usize = 52;

#[cfg(test)]
mod tests {
    use std::collections::HashSet;

    use super::{LONGEST_SUGGESTED, PG_FUNCTIONS, PG_SUGGESTED, is_suggested};

    /// [`is_suggested`] binary-searches, so an unsorted list answers `false`
    /// for names that are in it — a failure that shows up as a function
    /// quietly missing from the popup and nowhere else.
    #[test]
    fn the_subset_is_sorted_and_has_no_duplicates() {
        assert!(
            PG_SUGGESTED.windows(2).all(|w| w[0] < w[1]),
            "PG_SUGGESTED must be strictly ascending; first offender: {:?}",
            PG_SUGGESTED.windows(2).find(|w| w[0] >= w[1])
        );
    }

    /// Offering a name the catalog does not carry would be a completion row the
    /// checker then squiggles.
    #[test]
    fn every_suggested_name_is_in_the_catalog() {
        let all: HashSet<&str> = PG_FUNCTIONS.iter().map(|f| f.name).collect();
        let stray: Vec<&&str> = PG_SUGGESTED.iter().filter(|n| !all.contains(**n)).collect();
        assert!(
            stray.is_empty(),
            "PG_SUGGESTED names absent from PG_FUNCTIONS: {stray:?}"
        );
    }

    /// The fast reject in [`is_suggested`] is a hand-written number, so it is
    /// the kind that goes quietly wrong — too small and the longest names stop
    /// being offered without anything else changing.
    #[test]
    fn the_length_shortcut_rejects_nothing_real() {
        let longest = PG_SUGGESTED.iter().map(|n| n.len()).max().expect("names");
        assert_eq!(
            longest, LONGEST_SUGGESTED,
            "LONGEST_SUGGESTED is stale; the longest name is {longest} bytes"
        );
        for name in PG_SUGGESTED {
            assert!(is_suggested(name), "{name} is in the list and was rejected");
        }
    }

    /// The cut keeps what a person types and drops what the engine calls
    /// internally — including the grammar's own call forms, which a query over
    /// `pg_proc` cannot return and which a server-only subset would have lost.
    #[test]
    fn the_cut_falls_between_plumbing_and_sql() {
        for offered in [
            "coalesce",
            "cast",
            "trim",
            "greatest",
            "least",
            "nullif",
            "btrim",
            "date_trunc",
            "jsonb_set",
            "string_agg",
            "generate_series",
            "row_number",
        ] {
            assert!(is_suggested(offered), "{offered} should be offered");
        }
        for hidden in [
            "int4in",
            "int4out",
            "btint4cmp",
            "texteq",
            "int8_avg",
            "array_agg_transfn",
        ] {
            assert!(!is_suggested(hidden), "{hidden} is plumbing");
        }
    }

    /// The catalog is lower-case and the user is not.
    #[test]
    fn matching_ignores_case_at_the_callers_end() {
        assert!(is_suggested("COALESCE"));
        assert!(is_suggested("Jsonb_Set"));
        assert!(!is_suggested("INT4IN"));
        assert!(!is_suggested(""));
        assert!(!is_suggested(&"z".repeat(LONGEST_SUGGESTED + 1)));
    }
}
